  result[CommonFun.RoleData.EATTRTYPE_MDEF] = mdef
  result[CommonFun.RoleData.EATTRTYPE_CRI] = cri
  result[CommonFun.RoleData.EATTRTYPE_CRIRES] = math.max(lv / 6 - data.Luk / 5, 0)
