  result[CommonFun.RoleData.EATTRTYPE_DEX] = data.Dex
  result[CommonFun.RoleData.EATTRTYPE_INT] = data.Int
  result[CommonFun.RoleData.EATTRTYPE_VIT] = data.Vit
