  result[CommonFun.RoleData.EATTRTYPE_ATK] = math.floor(5000 * layer + math.max(layer - 6, 0) * 5000 + math.max(layer - 12, 0) * 5000 + math.max(layer - 18, 0) * 5000) + attr[CommonFun.RoleData.EATTRTYPE_ATK]
