function CommonFun.ModifyNumberDamage(srcUser, targetUser, params, logger, damage)
  if damage > 0 then
    local Count = params.hitedCount
    local SingleTargetDam = srcUser:GetProperty("SingleTargetDam")
    local MultipleTargetsDam = srcUser:GetProperty("MultipleTargetsDam")
    local SingleTargetRes = targetUser:GetProperty("SingleTargetRes")
    local MultipleTargetsRes = targetUser:GetProperty("MultipleTargetsRes")
    local SingleTarget = 1 + SingleTargetDam - SingleTargetRes
    SingleTarget = math.max(SingleTarget, 0.1)
    local MultipleTargets = 1 + MultipleTargetsDam - MultipleTargetsRes
    MultipleTargets = math.max(MultipleTargets, 0.1)
    if Count > 1 then
      damage = damage * MultipleTargets
    else
      damage = damage * SingleTarget
    end
  end
  return damage
end
function CommonFun.ModifyFinalDamage(srcUser, targetUser, params, logger, damage)
  if damage > 0 then
    local FinalDam = CommonFun.calcFinalDam(srcUser, targetUser, params, logger)
    local MonsterFinalDam = CommonFun.calcMonsterFinalDam(srcUser, targetUser, params, logger)
    local ResultDamInc = srcUser:GetProperty("ResultDamInc")
    local ResultDamRes = targetUser:GetProperty("ResultDamRes")
    local BossRealDam = srcUser:GetProperty("BossRealDam")
    local BossRealReduc = targetUser:GetProperty("BossRealReduc")
    if targetUser.boss == false then
      BossRealDam = 0
    end
    local Result = 1 + ResultDamInc - ResultDamRes
    Result = math.max(Result, 0.1)
    local BossResult = 1 + BossRealDam - BossRealReduc
    BossResult = math.max(BossResult, 0.01)
    damage = damage * FinalDam * MonsterFinalDam * Result * BossResult
  end
  return damage
end
