function CommonFun.CalcDamage(srcUser, targetUser, params, logger)
  local damage, damagetype = CommonFun.CalcBaseDamage(srcUser, targetUser, params, logger)
  local TaichiSecretLandGemLv = targetUser:GetSecretLandGemLv(384009)
  if (TaichiSecretLandGemLv ~= 0 or targetUser:HasBuffID(59570)) and damage > 0 then
    local reduceRatio = TaichiSecretLandGemLv * 0.002 + math.max(TaichiSecretLandGemLv - 30, 0) * 0.001 + math.max(TaichiSecretLandGemLv - 60, 0) * 0.002
    local reduceRatioOSK = 0.05
    if targetUser:HasBuffID(59570) then
      reduceRatio = reduceRatio + reduceRatioOSK
    end
    local loseValue = damage * reduceRatio
    damage = damage - loseValue
    if srcUser.isServerCall then
      targetUser:ChangeHpDuringTime(-loseValue, 3, srcUser:GetGuid())
    end
  end
  local skillID, skillLevel = CommonFun.UnmergeSkillID(params.skillIDAndLevel)
  local sharedam, realdam
  if damage > 0 then
    if targetUser.isServerCall then
      if targetUser.have_sharedam_server ~= nil and targetUser.have_sharedam_server == true then
        damage, sharedam, damagetype = CommonFun.CalcShareDamage(srcUser, targetUser, damage, damagetype)
      end
    else
      damage, sharedam, damagetype = CommonFun.CalcShareDamage(srcUser, targetUser, damage, damagetype)
    end
  end
  if damage > 0 and targetUser.diffShowDamage == true then
    local Level = srcUser.BaseLv
    local MonsterLevel = Table_MonsterLevel[Level]
    local MonsterID = targetUser:GetNpcID()
    local Monster = Table_Monster[MonsterID]
    if Monster ~= nil and MonsterLevel ~= nil then
      realdam = damage * Monster.Hp / MonsterLevel.RealMaxHp
    end
  end
  if damage > 0 and srcUser.diffShowDamage == true then
    local Level = targetUser.BaseLv
    local MonsterLevel = Table_MonsterLevel[Level]
    if MonsterLevel ~= nil then
      damage = damage * MonsterLevel.LevelReduc
    end
  end
  local shengwang = srcUser:GetPrestigeLevel()
  if damage > 0 and ((CommonFun.ispvp(srcUser, targetUser) or srcUser:InDamReduceRaid() == true) and srcUser:IsUserCamp() == true or shengwang ~= 0) then
    damage = CommonFun.GetDamReduceValue(srcUser, targetUser, damage)
    local skillParams = Table_Skill[params.skillIDAndLevel]
    if skillParams ~= nil and skillParams.DamRatio ~= nil then
      damage = damage * skillParams.DamRatio
    end
  end
  if damage > 0 then
    local skillParams = Table_Skill[params.skillIDAndLevel]
    if skillParams ~= nil and CommonFun.IsMultiTargetSkill(skillParams) == true and targetUser:HasBuffID(35010180) then
      local snowStoneLv385103 = targetUser:GetEquipSnowStoneLv(385103) or 0
      if snowStoneLv385103 > 0 then
        damage = damage * (1 - snowStoneLv385103 * 0.06)
      end
    end
    if skillParams ~= nil and CommonFun.IsMultiTargetSkill(skillParams) == true and (targetUser:HasBuffID(35010381) or targetUser:HasBuffID(35010382)) then
      local profressionID = srcUser:GetProfressionID()
      if profressionID ~= 114 and profressionID ~= 115 and profressionID ~= 104 and profressionID ~= 105 then
        local snowStoneLv385803 = targetUser:GetBuffLevel(35010381)
        local snowStoneLv385803a = targetUser:GetBuffLevel(35010382)
        local Stonevalue385803 = 0
        if snowStoneLv385803 > 0 then
          Stonevalue385803 = snowStoneLv385803 * 0.03 + 0.15
        end
        local Stonevalue385803a = 0
        if snowStoneLv385803a > 0 then
          Stonevalue385803a = snowStoneLv385803a * 0.03 + 0.15
        end
        if snowStoneLv385803 > 0 or snowStoneLv385803a > 0 then
          damage = damage * math.max(1 - Stonevalue385803 - Stonevalue385803a, 0)
        end
      end
    end
  end
  if (srcUser:HasBuffID(107480) or skillID == 4855 or skillID == 4856 or skillID == 4857 or skillID == 4858) and damage > 0 then
    if srcUser.isServerCall then
      targetUser:ChangeDamageToHpReduce(damage, srcUser:GetGuid(), params.skillIDAndLevel)
    end
    damage = 0
  end
  if damage > 0 and (srcUser:GetNpcID() == 580203 or srcUser:GetNpcID() == 580204) then
    local Master386402 = srcUser:GetMasterUser()
    if Master386402 ~= nil then
      local snowStoneLv386402 = Master386402:GetEquipSnowStoneLv(386402) or 0
      if snowStoneLv386402 > 0 then
        local autoSkillCount386402 = srcUser:GetBuffAutoSkillListCount() or 0
        damage = damage * (1 + autoSkillCount386402 * snowStoneLv386402 * 0.01)
      end
    end
  end
  if (CommonFun.DamageType.Normal == damagetype or CommonFun.DamageType.Crit == damagetype or CommonFun.DamageType.ErLianJi == damagetype or CommonFun.DamageType.VoiceBullet == damagetype) and damage >= 1 and targetUser:DamageAlways1() then
    damagetype = CommonFun.DamageType.Normal
    damage = 1
  end
  if damage >= 2147483647 then
    damage = 2147483647
  end
  targetUser:SetDoubleDamage(false)
  if damage > 0 then
    local damageDouble = CommonFun.calcOdds_18(srcUser, targetUser)
    if damageDouble > 0 then
      targetUser:SetDoubleDamage(true)
    elseif damageDouble < 0 then
      damagetype = CommonFun.DamageType.Miss
      damage = 0
    end
  end
  return damage, damagetype, sharedam, realdam
end
function CommonFun.CalcBaseDamage(srcUser, targetUser, params, logger)
  if nil == srcUser then
    logger.error(string.format("srcUser is nil"))
    return 0, CommonFun.DamageType.None
  end
  if nil == targetUser then
    logger.error(string.format("targetUser is nil"))
    return 0, CommonFun.DamageType.None
  end
  if nil == Table_Skill then
    logger.error("Table_Skill is nil")
    return 0, CommonFun.DamageType.None
  end
  local skillParams = Table_Skill[params.skillIDAndLevel]
  if nil == skillParams then
    logger.error(string.format("Table_Skill[%d] is nil", params.skillIDAndLevel))
    return 0, CommonFun.DamageType.None
  end
  local paramList = skillParams.Damage
  if nil == paramList or #paramList <= 0 then
    return 0, CommonFun.DamageType.None
  end
  local mapid, maptype = srcUser:GetMapInfo()
  local iscrit = CommonFun.IsCrit(srcUser, targetUser, skillParams)
  local damageType = CommonFun.DamageType.Normal
  local damage, forceDamageType = CommonFun.DoCalcDamage(srcUser, targetUser, params, logger)
  local skillID, skillLevel = CommonFun.UnmergeSkillID(params.skillIDAndLevel)
  local snowStone385505TriggerCrit = false
  if iscrit == false and CommonFun.RollType.Attack == skillParams.RollType and (srcUser:IsAttackSkill(params.skillIDAndLevel) or srcUser:IsExtraNormalSkill(params.skillIDAndLevel)) then
    local snowStoneLv385505 = srcUser:GetEquipSnowStoneLv(385505) or 0
    if snowStoneLv385505 > 0 then
      if 0 < (srcUser:GetBuffLayer(130503) or 0) then
        iscrit = true
        snowStone385505TriggerCrit = true
      end
    end
  end
  if srcUser:HasBuffID(107480) == false and skillID ~= 4855 and skillID ~= 4856 and skillID ~= 4857 and skillID ~= 4858 then
    local miss_dam, miss_damtype = CommonFun.CheckMissAndBlock(srcUser, targetUser, params, skillParams, iscrit, damage)
    if miss_damtype ~= nil then
      return miss_dam, miss_damtype
    end
    if nil ~= forceDamageType then
      damageType = forceDamageType
      if CommonFun.DamageType.None == damageType or CommonFun.DamageType.Miss == damageType or CommonFun.DamageType.Block == damageType then
        return damage, damageType
      end
    elseif 0 == damage then
      return 0, CommonFun.DamageType.WeaponBlock
    elseif damage < 0 then
      damageType = CommonFun.DamageType.Treatment
    end
    if snowStone385505TriggerCrit and srcUser.isServerCall then
      srcUser:AddBuff(35010751, srcUser:GetGuid())
    end
  end
  if nil ~= forceDamageType then
    damageType = forceDamageType
  end
  if (damageType == nil or damageType == CommonFun.DamageType.Normal or damageType == CommonFun.DamageType.Crit) and iscrit and CommonFun.RollType.Attack == skillParams.RollType and (srcUser:IsAttackSkill(params.skillIDAndLevel) or srcUser:IsExtraNormalSkill(params.skillIDAndLevel)) then
    damageType = CommonFun.DamageType.Crit
    damage = CommonFun.ModifyCriDamage(srcUser, targetUser, params, logger, skillParams, damage)
  end
  local GetNpcID = targetUser:GetNpcID()
  local GetSelfID = srcUser:GetNpcID()
  if damage > 0 and GetNpcID == 30034 and srcUser:HasBuffID(121) then
    local Atk = srcUser:GetProperty("Atk")
    local MAtk = srcUser:GetProperty("MAtk")
    damage = damage + (Atk + MAtk) * 2.5
  end
  if targetUser:HasBuffID(10740) and srcUser:HasBuffID(10741) == false then
    damage = 0.2
  end
  local skillID, skillLevel = CommonFun.UnmergeSkillID(params.skillIDAndLevel)
  damage = CommonFun.ModifyRealDam(srcUser, targetUser, params, skillParams, damage, skillID, maptype)
  if GetNpcID == 40021 or GetNpcID == 40022 or GetNpcID == 55000 or GetNpcID == 40023 or GetNpcID == 40024 or GetNpcID == 40026 then
    local forcetype
    damage, forcetype = CommonFun.ModifyMetalNpcDamage(srcUser, targetUser, params, damage, skillID, GetNpcID)
    if forcetype ~= nil then
      return damage, forcetype
    end
  end
  local AttrEffect2 = targetUser:GetProperty("AttrEffect")
  local bits2 = CommonFun.getBits(AttrEffect2)
  if damage > 0 and (targetUser:GetNpcID() == 56941 or targetUser:GetNpcID() == 56942) and srcUser:GetNpcID() ~= 56941 and srcUser:GetNpcID() ~= 56942 then
    return 1, CommonFun.DamageType.Normal
  end
  if damage > 0 and targetUser:GetNpcID() == 300100 and srcUser:HasBuffID(180220) then
    damage = damage * 1.3
  end
  if damage > 0 and srcUser:GetNpcID() == 300100 and targetUser:HasBuffID(180219) then
    damage = damage * 0.5
  end
  if damage > 0 and targetUser:GetNpcID() == 300101 and srcUser:HasBuffID(180518) then
    damage = damage * 1.25
  end
  if damage > 0 and srcUser:GetNpcID() == 300101 and targetUser:HasBuffID(180517) then
    damage = damage * 0.7
  end
  if (targetUser:HasBuffID(100660) == true or targetUser:HasBuffID(21430114) == true) and damage > 0 then
    local GemValue = targetUser:GetProperty("JinGangRate")
    local JGBH = 1
    JGBH = 0.15 - GemValue
    local skilllv_ab = srcUser:GetLernedSkillLevel(306)
    if skilllv_ab > 5 and skillID == 306 or skillID == 3303 or skillID == 819 then
      JGBH = 1
    end
    damage = math.floor(damage * JGBH)
  end
  if targetUser:HasBuffID(117105) == true and damage > 0 then
    local skilllv_zfz = targetUser:GetBuffLevel(117105)
