function CommonFun.GetVoiceBulletCount(creature)
  if creature == nil then
    return 1
  end
  local AtkSpd = creature:GetProperty("AtkSpd") or 0
  local count = math.floor(AtkSpd) + 1
  if count < 1 then
    count = 1
  elseif count > 5 then
    count = 5
  end
  return count
end
function CommonFun.GetVoiceBulletDamageParam(creature)
  return CommonFun.GetVoiceBulletCount(creature)
end
