  local Vit = targetUser:GetProperty("Vit")
  local Int = targetUser:GetProperty("Int")
  local A = math.min(0.8, Luk * 0.3 / 100)
  local B = math.min(1, (Vit * 0.2 + Int * 0.2) / 100)
  local Rate = 1 + A - B
  if Rate <= 0 then
    Rate = 0
  end
  return Rate
end
