    return ExtraScore
  end
end
function CommonFun.getExpExtra(npczone, npctype, stype, mapid)
  local extra = 0
  local mextra = 0
  local cur = os.time()
  if npczone == 1 then
    local starttime = os.time({
      year = 2016,
      month = 2,
      day = 24,
      hour = 9,
      min = 10
    })
    local endtime = os.time({
      year = 2016,
      month = 2,
      day = 28,
      hour = 9,
      min = 10
    })
    if cur >= starttime and cur <= endtime then
      extra = 0.5
    end
  elseif npczone == 3 then
    local starttime = os.time({
      year = 2016,
      month = 2,
      day = 25,
      hour = 9,
      min = 10
    })
    local endtime = os.time({
      year = 2016,
      month = 2,
      day = 28,
      hour = 9,
      min = 10
    })
    if cur >= starttime and cur <= endtime then
      extra = 1
    end
  elseif npczone == 4 then
    local starttime = os.time({
      year = 2016,
      month = 2,
      day = 25,
      hour = 9,
      min = 10
    })
    local endtime = os.time({
      year = 2016,
      month = 2,
      day = 26,
      hour = 9,
      min = 10
    })
    if cur >= starttime and cur <= endtime then
      extra = 2
    end
  elseif npczone == 5 then
    local starttime = os.time({
      year = 2016,
      month = 2,
      day = 25,
      hour = 9,
      min = 10
    })
    local endtime = os.time({
      year = 2016,
      month = 2,
      day = 26,
      hour = 9,
      min = 10
    })
    if cur >= starttime and cur <= endtime then
      extra = 3
    end
  end
  local mapgroup = {
    [1] = 0.5,
    [2] = 2
  }
  local starttime = os.time({
    year = 2016,
    month = 2,
    day = 27,
    hour = 11,
    min = 15
  })
  local endtime = os.time({
    year = 2016,
    month = 2,
    day = 28,
    hour = 11,
    min = 20
  })
  if cur >= starttime and cur <= endtime then
    if stype == 1 then
      if #mapgroup == 0 then
        mextra = 0
      else
        for k, v in pairs(mapgroup) do
          if k == mapid then
            mextra = v
            break
          end
        end
      end
    elseif npczone == 1 and (npctype == 3 or npctype == 4 or npctype == 5) then
      if #mapgroup == 0 then
        mextra = 0
      else
        for k, v in pairs(mapgroup) do
          if k == mapid then
            mextra = v
            break
          end
        end
      end
    end
  end
  return extra + mextra
end
function CommonFun.getItemReduceValue(deltalv, star)
  local extrper = 0
  local extrper1 = 0
  local extrper2 = 0
  if deltalv >= -40 then
    extrper1 = 1
  elseif deltalv >= -50 and deltalv <= -41 then
    extrper1 = 0.9
  elseif deltalv >= -60 and deltalv <= -51 then
    extrper1 = 0.8
  elseif deltalv >= -70 and deltalv <= -61 then
    extrper1 = 0.7
  elseif deltalv < -70 then
    extrper1 = 0.6
  end
  if deltalv >= -30 then
    extrper2 = 1
  elseif deltalv >= -40 and deltalv <= -31 then
    extrper2 = 0.9
  elseif deltalv >= -50 and deltalv <= -41 then
    extrper2 = 0.8
  elseif deltalv >= -60 and deltalv <= -51 then
    extrper2 = 0.7
  elseif deltalv >= -70 and deltalv <= -61 then
    extrper2 = 0.6
  elseif deltalv < -70 then
    extrper2 = 0.5
  end
  if star ~= nil and star == true then
    extrper = extrper1
  else
    extrper = extrper2
  end
  return extrper
end
