function CommonFun.GetRandom(array, index)
  local MAX_RANDOM_INDEX = 100
  local group = math.ceil(index / 5)
  local key = index - math.floor(index / 5) * 5
  if key == 0 or not key then
    key = 5
  end
  if array[group] == nil or index > MAX_RANDOM_INDEX then
    return 0, index
  end
  local groupValue = array[group]
  local value = math.floor(groupValue / math.pow(100, 5 - key)) % 100
  local newIndex = index == MAX_RANDOM_INDEX and 1 or index + 1
  return value, newIndex
end
function CommonFun.CalcTeamPwsScore(winteam_ave, loseteam_ave, winmax, losemax, selfscore, iswin, extrascore, delta_server_ave)
  local user_score = 0
  local winscore = 0
  local losescore = 0
  if selfscore < 500 then
    winscore = 100
    losescore = 50
  elseif selfscore < 1200 then
    winscore = 100
    losescore = 20
  elseif selfscore < 2000 then
    winscore = 100
    losescore = 0
  elseif selfscore < 2600 then
    winscore = 100
    losescore = -30
  elseif selfscore < 3000 then
    winscore = 100
    losescore = -70
  else
    winscore = 100
    losescore = -120
  end
  local selfscore0 = selfscore
  if winteam_ave >= 3000 then
    winteam_ave = winteam_ave + (winteam_ave - 3000) * 9
  end
  if loseteam_ave >= 3000 then
    loseteam_ave = loseteam_ave + (loseteam_ave - 3000) * 9
  end
  if selfscore0 >= 3000 then
    selfscore = selfscore0 + (selfscore0 - 3000) * 9
  end
  local serverdiff = 0
  if delta_server_ave < 0 then
    local ave = math.abs(delta_server_ave)
    serverdiff = 0.0052 * math.pow(ave, 3) - 0.086 * math.pow(ave, 2) + 0.491 * ave - 0.0276
  end
  if serverdiff < 0 then
    serverdiff = 0
  end
  if iswin == true then
    local a = loseteam_ave - winteam_ave
    local b = selfscore - winteam_ave + 100
    local c = 1
    local grouppara = 1
    if 50 >= math.abs(a) then
      a = 1
    end
    if b <= -250 then
      b = -250
    end
    local avepara = 0.1 * math.sin(math.min(math.abs(a), 400) * math.pi / 800) * math.abs(a) / a
    if math.abs(b) > 150 then
      grouppara = 1 / math.tan((math.min(math.abs(b), 480) - 0.1) / 1000 * math.pi) * ((math.min(math.abs(b), 480) - 0.1) / 1000 * math.pi)
    end
    if b > 500 then
      c = (1000 - math.min(1000, b)) / 1000
    end
    user_score = math.max((1.1 + avepara) * (0.2 * c + 0.8 * grouppara) * winscore * (1 + serverdiff * 0.1), 1)
  end
  if iswin == false then
    if selfscore < 2000 then
      local a = winteam_ave - loseteam_ave
      local b = selfscore - loseteam_ave + 100
      if 50 >= math.abs(a) then
        a = 1
      end
      if b <= -250 then
        b = -250
      end
      local grouppara = 1
      local avepara = 0.1 * math.sin(math.min(math.abs(a), 400) * math.pi / 800) * math.abs(a) / a
      if math.abs(b) > 150 then
        grouppara = 1 / math.tan((math.min(math.abs(b), 480) - 0.1) / 1000 * math.pi) * ((math.min(math.abs(b), 480) - 0.1) / 1000 * math.pi)
      end
      user_score = math.max((1.1 + avepara) * (0.2 + 0.8 * grouppara) * losescore * (1 + serverdiff * 0.25), 1)
    elseif selfscore >= 2000 then
      local a = winteam_ave - loseteam_ave
      local b = selfscore - loseteam_ave + 100
      if 50 >= math.abs(a) then
        a = 1
      end
      if b <= -250 then
        b = -250
      end
      local grouppara = 0.25
      local avepara = -0.1 * math.sin(math.min(math.abs(a), 400) * math.pi / 800) * math.abs(a) / a
      if a > 50 then
        avepara = -(2.0E-4 * math.pow(a / 100, 5) - 0.0052 * math.pow(a / 100, 4) + 0.0417 * math.pow(a / 100, 3) - 0.1106 * math.pow(a / 100, 2) + 0.1406 * a / 100 - 0.0037)
      end
      if b > 150 then
        grouppara = 0.75 * math.sin(math.min(math.abs(b), 480) * math.pi / 1000) * math.abs(b) / b
      end
      if b < -150 then
        grouppara = 0.25 * math.sin(math.min(math.abs(b), 480) * math.pi / 1000) * math.abs(b) / b
      end
      user_score = math.min((1 + avepara) * (0.75 + grouppara) * losescore * (1 - serverdiff * 0.25), -1)
    end
  end
  if user_score + selfscore + extrascore >= 3000 then
    user_score = 3000 + (user_score + selfscore + extrascore - 3000) / 10 - selfscore0
  else
    user_score = user_score + selfscore + extrascore - selfscore0
  end
  return user_score
end
function CommonFun.CalcRaidDeadBossSummonLevel(raidtype, param)
  local a = math.random(0, 100)
  local boss_lv = 1
  if raidtype == 5 then
    if param == 1 then
      return 0
    elseif param == 2 then
      boss_lv = 1
    elseif param == 3 then
      if a < 50 then
        boss_lv = 2
      else
        boss_lv = 3
      end
    elseif param == 4 then
      if a < 50 then
        boss_lv = 4
      else
        boss_lv = 5
      end
    end
  end
  return boss_lv
end
