function calcDecomposeResult(param)
  if param >= 500 and param <= 750 then
    return 2
  elseif param >= 800 and param <= 1200 then
    return 3
  elseif param >= 1250 and param <= 1450 then
    return 4
  elseif param >= 1500 then
    return 5
  end
  return 1
end
function getRefineParam(refinelv)
  local refineparam = {
    [1] = 1,
