    return itemcount * 3
  elseif submitcount == 6 then
    return itemcount * 4
  end
  return itemcount * 4
end
function CommonFun.calcArtifactMaterialItemCount(type, num, count)
  if type == 1 then
    return num
  elseif type == 2 then
    if count == 0 then
      return num
    elseif count == 1 then
      return num
    elseif count == 2 then
      return math.ceil(num * 1.5)
    else
      return num * 2
    end
  elseif count == 0 then
    return num
  elseif count == 1 then
    return num
  elseif count == 2 then
    return math.ceil(num * 1.5)
  else
    return num * 2
  end
end
function CommonFun.calcValidDFSPNum(maxjoblv, limitnum, packageown)
  if maxjoblv > 160 then
    return 0
  elseif maxjoblv <= 133 then
    return limitnum - packageown
  else
    return limitnum - (maxjoblv - 133) * 3 - packageown
  end
end
